// SPDX-License-Identifier: GPL-3.0-or-later
// DM32 Plus art (CONFIG_PLUS_ART, docs/art.md): 16x16 icons tinted with one color, the splash mark and the
// "DDM32 Plus" wordmark. All of it is const data in flash (art_data.c, generated by tools/art_build.py); drawing
// goes through gfx_fill in horizontal runs and keeps no state, so it costs no RAM beyond a few stack words.
#ifndef PLUS_ART_H
#define PLUS_ART_H

#include <stdint.h>
#include <stdbool.h>
#ifdef ART_HOST_TEST
#define ART_ENABLED	1
#else
#include "config.h"
#define ART_ENABLED	CONFIG_PLUS_ART	// off: art.c, art_data.c and splash_plus.c compile to nothing
#endif
#include "art_data.h"

// The product name on the radio, its author and the author's amateur callsign (owner's request 2026-11-19). Names,
// not sentences: never translated. The splash shows the callsign small at the bottom centre, About all three on one
// line (tools/plus_brand.py). Upstream's credits (RadioFoundry, MIT; Open25-DM32, GPL-3.0) stay beside them
#define ART_PRODUCT	"DDM32 Plus"
#define ART_AUTHOR	"d0ukan"
#define ART_CALLSIGN	"TA2DOU"

// An icon (ART_ICON_*) with its top left corner at x, y: ink pixels in color, the rest left as it is. An id out of
// range draws nothing
void art_icon(unsigned id, int x, int y, uint16_t color);

// The splash mark at x, y, each source pixel a scale x scale block (scale 1..4). Its own colors on a color panel;
// mono: colors marked ink in fg, the others in bg
void art_mark(int x, int y, int scale, bool mono, uint16_t fg, uint16_t bg);

// The wordmark at x, y, scale as above: "DDM32" in fg, "Plus" in accent
void art_wordmark(int x, int y, int scale, uint16_t fg, uint16_t accent);

// The accent color of the art (the mark's tile color), for the wordmark and a rule under it on color panels
uint16_t art_accent(void);

// Mark over wordmark, centered on cx, from y down; returns the height drawn (art_splash_h)
int art_splash(int cx, int y, int scale, bool mono, uint16_t fg, uint16_t bg);
int art_splash_h(int scale);
int art_splash_w(int scale);

// The boot screen with the DDM32 Plus art (splash_plus.c; tests/plus/test_art.c draws it on stand-ins): the same
// arguments as ui_draw_splash. False when the panel is too small for the art (ui_draw_splash then draws its own)
bool ui_draw_splash_plus(const char *board_name, const char *version, const char *line1, const char *line2);

#endif
